$_MODULE['<{gmerchantcenterpro}prestashop>feed-settings_5c0cd3b0d08c878903362281e57e8f8a'] = 'Si algunos de sus productos tienen al mismo tiempo un código UPC, puede especificar en el módulo qué código mirar de forma prioritaria. Por ejemplo, si su tienda utiliza principalmente códigos EAN13/JAN (y códigos UPC solo para algunos productos), probablemente querrá que el módulo compruebe primero si hay algún código EAN13/JAN y, si se da el caso, que lo utilice. Si el valor no está disponible, el módulo irá a comprobar el valor del UPC y lo utilizará si se encuentra presente.';
